def word_frequency(paragraph):
    word_dict = {}
    words = paragraph.lower().split()
    for word in words:
        if word.isalpha():
            if word in word_dict:
                word_dict[word] += 1
            else:
                word_dict[word] = 1
    return word_dict
```

